/* M03 — shared local royalty workflow. Nothing is posted to a live service. */
const ui107={tab:'summary',period:'2026-09',query:'',platform:'',country:'',artist:'',release:'',kind:'',sort:'desc',filters:false,importFilter:'all',batch:null,detailTab:'summary',contract:null,minimized:false};
const tr107=(a,b)=>T(a,b), btn107=(text,action,id='',cls='')=>['export','report-download','csv','excel'].includes(action)&&!canExport107()?'':`<button type="button" class="btn ${cls}" data-r107="${action}" data-id="${E(id)}">${text}</button>`;
const money107=n=>new Intl.NumberFormat(ten.lang==='en'?'en-US':'id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
const actor107=()=>({role:ten.role,member:isLabel10()?ten.member:undefined});
function model107(){return ten.royalty107??=(Royalty107.seed(ten.members))}
const month107=p=>new Intl.DateTimeFormat(ten.lang==='en'?'en-GB':'id-ID',{month:'long',year:'numeric'}).format(new Date(p+'-01T12:00:00'));
const date107=x=>new Intl.DateTimeFormat(ten.lang==='en'?'en-GB':'id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(x));
const memberName107=id=>RM10.getMember(ten,id)?.name||tr107('Pemilik belum diketahui','Unassigned owner');
const empty107=text=>`<div class="empty107">${text}</div>`;
const opt107=(v,text,selected)=>`<option value="${E(v)}" ${v===selected?'selected':''}>${E(text)}</option>`;
const pill107=(text,tone='')=>`<span class="pill107 ${tone}107">${text}</span>`;
function post107(action,p){if(!eligible107())throw Error(tr107('Akses tidak tersedia.','Access unavailable.'));return atomic10(()=>Royalty107.act(model107(),actor107(),action,p))}
function eligible107(){return isLabel10()||ten.role==='super'||allowedModule(modules.find(m=>m.id==='imports'))}
function royaltyRoute107(id='analytics'){closeModal();ui107.batch=null;state.page='module';state.mode='platform';v4.module=id;render();window.scrollTo({top:0,behavior:'instant'})}
function safeRows107(){return Royalty107.rows(model107(),actor107())}
function filtered107(){const q=ui107.query.toLowerCase();return safeRows107().filter(r=>(!ui107.period||r.period===ui107.period)&&(!q||[r.title,r.artist,r.isrc,r.upc,r.release].join(' ').toLowerCase().includes(q))&&['platform','country','artist','release','kind'].every(k=>!ui107[k]||r[k]===ui107[k]));}
function grouped107(rs){const groups=new Map();for(const r of rs){const key=r.member+'|'+(r.isrc||r.track);if(!groups.has(key))groups.set(key,{...r,key,amount:0,platforms:new Set(),rows:[]});const x=groups.get(key);x.amount+=r.amount;x.platforms.add(r.platform);x.rows.push(r);}return [...groups.values()].sort((a,b)=>ui107.sort==='title'?a.title.localeCompare(b.title):ui107.sort==='asc'?a.amount-b.amount:b.amount-a.amount)}
const total107=rs=>rs.reduce((n,r)=>n+r.amount,0);
function cover107(r){const release=ten.releases.find(x=>x.member===r.member&&(x.upc&&x.upc===r.upc||x.songs?.some(t=>t.isrc===r.isrc)));return release?.cover?.url?`<img class="cover107" src="${E(release.cover.url)}" alt="">`:'<span class="cover107" aria-hidden="true">♫</span>'}
function periodSelect107(){const periods=[...new Set(safeRows107().map(r=>r.period))].sort().reverse();if(ui107.period&&!periods.includes(ui107.period))periods.unshift(ui107.period);return `<label class="muted107">${tr107('Periode laporan','Report period')} <select data-f107="period" aria-label="${tr107('Periode laporan','Report period')}">${opt107('',tr107('Semua periode','All periods'),ui107.period)}${periods.map(p=>opt107(p,month107(p),ui107.period)).join('')}</select></label>`}
function bars107(rs,field){const g={};rs.forEach(r=>g[r[field]]=(g[r[field]]||0)+r.amount);const total=total107(rs);return Object.entries(g).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([key,n])=>`<div class="barrow107"><span>${E(key||'—')}</span><strong>${money107(n)}</strong><div class="bar107"><i style="width:${total>0?Math.min(100,Math.max(0,n/total*100)):0}%"></i></div><small>${total>0?(n/total*100).toFixed(1)+'%':'—'}</small></div>`).join('')||empty107(tr107('Belum ada data pada periode ini.','No data for this period.'))}
function trackTable107(rs=filtered107(),detail=true){const groups=grouped107(rs),total=total107(rs);return `<div class="table107"><table><thead><tr><th>${tr107('Lagu / rilisan','Track / release')}</th><th>${tr107('Artis','Artist')}</th><th>Platform</th><th class="number107">${tr107('Pendapatan','Earnings')}</th><th class="number107">${tr107('Kontribusi','Contribution')}</th><th></th></tr></thead><tbody>${groups.map(g=>`<tr><td><div class="track107">${cover107(g)}<div>${detail?btn107(E(g.title),'track',g.key,'text'):'<strong>'+E(g.title)+'</strong>'}<small>${E(g.release)}</small></div></div></td><td>${E(g.artist)}</td><td>${g.platforms.size}</td><td class="number107 ${g.amount<0?'negative107':''}">${money107(g.amount)}</td><td class="number107">${total>0?(g.amount/total*100).toFixed(1)+'%':'—'}</td><td>${detail?btn107('↗','track',g.key,'arrow107'):''}</td></tr>`).join('')||`<tr><td colspan="6">${empty107(tr107('Tidak ada pendapatan yang sesuai filter.','No earnings match these filters.'))}</td></tr>`}</tbody></table></div>`}
function filterPanel107(){return `<div class="filters107">${['artist','release','platform','country','kind'].map((key,i)=>`<label>${[tr107('Artis','Artist'),tr107('Rilisan','Release'),'Platform',tr107('Negara','Country'),tr107('Jenis penggunaan','Usage type')][i]}<select data-f107="${key}">${opt107('',tr107('Semua','All'),ui107[key])}${[...new Set(safeRows107().map(r=>r[key]).filter(Boolean))].sort().map(v=>opt107(v,v,ui107[key])).join('')}</select></label>`).join('')}${btn107(tr107('Reset filter','Reset filters'),'reset','','text')}</div>`}
function summary107(){const rs=safeRows107().filter(r=>!ui107.period||r.period===ui107.period),all=safeRows107(),metrics=[[tr107('Pendapatan periode','Period earnings'),money107(total107(rs))],[tr107('Lagu menghasilkan','Earning tracks'),new Set(rs.filter(r=>r.amount>0).map(r=>r.member+'|'+r.isrc)).size],[tr107('Artis menghasilkan','Earning artists'),new Set(rs.filter(r=>r.amount>0).map(r=>r.artist)).size],['Platform',new Set(rs.map(r=>r.platform)).size],[tr107('Wilayah','Territories'),new Set(rs.map(r=>r.country)).size]];const periods=[...new Set(all.map(r=>r.period))].sort().slice(-6),totals=periods.map(p=>total107(all.filter(r=>r.period===p))),max=Math.max(1,...totals.map(Math.abs));return `<div class="metrics107">${metrics.map(([a,b])=>`<article class="metric107"><small>${a}</small><strong>${rs.length?b:'—'}</strong></article>`).join('')}</div>${!rs.length?`<section class="panel107">${empty107(tr107('Laporan untuk periode ini belum tersedia.','The report for this period is not available yet.'))}</section>`:`<div class="grid107"><section class="panel107"><h2>${tr107('Perkembangan pendapatan','Earnings over time')}</h2><p>${tr107('Berdasarkan periode laporan yang sudah diterbitkan.','Based on published reporting periods.')}</p><div class="chart107">${periods.map((p,i)=>`<div class="chart-col107"><b>${money107(totals[i])}</b><i style="height:${Math.max(2,Math.abs(totals[i])/max*100)}%;opacity:${!ui107.period||p===ui107.period?1:.4}"></i><span>${E(month107(p))}</span></div>`).join('')}</div></section><section class="panel107"><h2>${tr107('Kontribusi platform','Platform contribution')}</h2>${bars107(rs,'platform')}</section><section class="panel107"><h2>${tr107('Lagu dengan pendapatan tertinggi','Top earning tracks')}</h2>${trackTable107(grouped107(rs).slice(0,5).flatMap(g=>g.rows))}</section><section class="panel107"><h2>${tr107('Wilayah penggunaan','Usage territories')}</h2><p>${tr107('Lokasi penggunaan atau penjualan dalam laporan distribusi.','Usage or sales territories in distribution reports.')}</p>${bars107(rs,'country')}</section></div>`}`}
function reports107(){const rs=safeRows107(),periods=[...new Set(rs.map(r=>r.period))].sort().reverse().filter(p=>!ui107.period||p===ui107.period);return `<section class="panel107"><div class="table107"><table><thead><tr>${[tr107('Periode laporan','Report period'),tr107('Pendapatan label','Label earnings'),tr107('Diperbarui pada','Updated'),tr107('Tindakan','Actions')].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${periods.map(p=>{const rows=rs.filter(r=>r.period===p),batchIds=new Set(rows.map(r=>r.batch)),latest=model107().history.filter(h=>batchIds.has(h.ref)&&['publish','correct'].includes(h.kind)).at(-1);return `<tr><td><strong>${month107(p)}</strong><small>${batchIds.size} ${tr107('sumber laporan','report sources')}</small></td><td>${money107(total107(rows))}</td><td>${latest?date107(latest.at):'—'}</td><td>${btn107(tr107('Lihat laporan','View report'),'report',p)} ${btn107(tr107('Unduh','Download'),'report-download',p,'text')}</td></tr>`}).join('')||`<tr><td colspan="4">${empty107(tr107('Belum ada laporan yang diterbitkan.','No published reports yet.'))}</td></tr>`}</tbody></table></div></section>`}
function labelRoyalty107(){if(!eligible107())return empty107(tr107('Menu tidak tersedia.','Menu unavailable.'));const bal=isLabel10()?Royalty107.balance(model107(),ten.member):null;return `<div class="royalty107"><header class="head107"><div><span class="eyebrow107">ROYALTY · RILIS MUSIK</span><h1>${tr107('Royalti','Royalties')}</h1><p>${tr107('Kenali pendapatan katalogmu, hingga ke setiap lagu.','Understand your catalogue earnings, down to every track.')}</p></div>${periodSelect107()}</header>${bal?`<section class="balance107"><div><small>${tr107('Saldo tersedia saat ini','Current available balance')}</small><strong>${money107(bal.available)}</strong><small>${tr107('Tidak mengikuti filter periode laporan.','Independent of the reporting-period filter.')}</small></div><div class="actions107">${btn107(tr107('Lihat rincian saldo','View balance details'),'balance','','text')}${btn107(tr107('Ajukan penarikan','Request withdrawal'),'withdraw','','primary')}</div></section>`:''}<nav class="tabs" data-switch-key105="royalty-label107">${[['summary','Ringkasan','Overview'],['details','Rincian pendapatan','Earnings details'],['reports','Laporan','Reports']].map(([id,a,b])=>btn107(tr107(a,b),'tab',id,ui107.tab===id?'active':'')).join('')}</nav>${ui107.tab==='summary'?summary107():ui107.tab==='reports'?reports107():`<div class="toolbar107"><input id="royalty-search107" type="search" value="${E(ui107.query)}" placeholder="${tr107('Cari lagu, artis, UPC atau ISRC','Search track, artist, UPC or ISRC')}"><div class="actions107">${btn107(tr107('Filter','Filters')+' ≡','filters','',ui107.filters?'selected':'')}<select data-f107="sort" aria-label="${tr107('Urutkan','Sort')}">${[['desc','Pendapatan tertinggi','Highest earnings'],['asc','Pendapatan terendah','Lowest earnings'],['title','Judul lagu','Track title']].map(([id,a,b])=>opt107(id,tr107(a,b),ui107.sort)).join('')}</select>${btn107(tr107('Unduh rincian','Download details'),'export','','primary')}</div></div>${ui107.filters?filterPanel107():''}<p class="muted107">${grouped107(filtered107()).length} ${tr107('lagu','tracks')} · ${tr107('Total pendapatan','Total earnings')} ${money107(total107(filtered107()))}${['artist','release','platform','country','kind'].filter(k=>ui107[k]).map(k=>' · '+E(ui107[k])).join('')}</p><section class="panel107">${trackTable107()}</section>`}</div>`}
function drawer107(title,body){document.querySelector('#royalty-drawer107')?.remove();const d=document.createElement('dialog');d.id='royalty-drawer107';d.className='release-drawer106 royalty107';d.innerHTML=`<header><h2>${E(title)}</h2>${btn107('×','close-drawer','','icon-close106')}</header>${body}`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal()}
function track107(key){const source=ui107.tab==='summary'?safeRows107().filter(r=>!ui107.period||r.period===ui107.period):filtered107();const g=grouped107(source).find(g=>g.key===key);if(!g)return;drawer107(g.title,`<div class="track107">${cover107(g)}<div><strong>${E(g.artist)}</strong><small>${E(g.release)}</small></div></div><div class="report-hero107"><span class="muted107">${E(g.isrc||'—')}</span><strong>${money107(g.amount)}</strong><small>${tr107('Pendapatan sesuai periode dan filter pilihan.','Earnings for the selected period and filters.')}</small></div>${g.rows.map(r=>`<div class="history107"><div><strong>${E(r.platform)} · ${E(r.country)}</strong><small style="display:block">${E(r.kind)} · ${r.quantity??'—'} ${/stream/i.test(r.kind)?tr107('pemutaran','plays'):/download/i.test(r.kind)?tr107('unduhan','downloads'):tr107('unit','units')}</small><small style="display:block">${tr107('Laporan','Report')} ${month107(r.period)} · ${tr107('Penggunaan','Usage')} ${E(r.sales||'—')}</small></div><strong>${money107(r.amount)}</strong></div>`).join('')}<p class="note107">${tr107('Pendapatan lagu bukan saldo yang dapat ditarik secara terpisah.','Track earnings are not a separately withdrawable balance.')}</p>${ten.releases.some(r=>r.member===g.member&&r.upc===g.upc)?btn107(tr107('Lihat rilisan','View release'),'catalogue',g.upc,'primary'):''}`)}
function report107(period){const rs=safeRows107().filter(r=>r.period===period);if(!rs.length)return;const corrections=model107().corrections.filter(c=>rs.some(r=>r.batch===c.batch&&r.member===c.member));reviewDialogUI(tr107('Laporan royalti','Royalty report'),`<div class="royalty107"><div class="report-hero107"><span class="eyebrow107">${isLabel10()?E(member10().name):'RILIS MUSIK'}</span><h2>${month107(period)}</h2><small>${tr107('Versi terbaru','Latest version')} · ${[...new Set(rs.map(r=>r.batch+' / v'+r.version))].join(' · ')}</small><strong>${money107(total107(rs))}</strong><p class="muted107">${tr107('Pendapatan periode; tidak berubah akibat penarikan saldo.','Period earnings; unaffected by balance withdrawals.')}</p></div>${trackTable107(rs,false)}<div class="actions107">${btn107('Excel','excel',period,'primary')}${btn107('CSV','csv',period)}</div>${corrections.length?`<h3>${tr107('Riwayat pembaruan','Revision history')}</h3>${corrections.map(c=>`<div class="history107"><div><strong>${money107(c.before)} → ${money107(c.after)}</strong><p>${E(c.reason)}</p><small>${date107(c.at)} · ${tr107('Versi sebelumnya tersimpan','Previous version retained')}</small></div>${btn107(tr107('Lihat versi','View version'),'old-report',c.id)}</div>`).join('')}`:''}</div>`)}
function balance107(){if(!isLabel10())return;const s=model107(),bal=Royalty107.balance(s,ten.member);drawer107(tr107('Rincian saldo','Balance details'),`<div class="report-hero107"><small>${tr107('Saldo tersedia saat ini','Current available balance')}</small><strong>${money107(bal.available)}</strong></div><div class="history107"><span>${tr107('Pendapatan menunggu dana','Earnings awaiting funds')}</span><strong>${money107(bal.pending)}</strong></div>${s.ledger.filter(l=>l.member===ten.member).slice().reverse().map(l=>`<div class="history107"><div>${E(l.ref)}<small style="display:block">${l.bucket==='available'?tr107('Saldo tersedia','Available balance'):tr107('Menunggu dana','Awaiting funds')} · ${date107(l.at)}</small></div><strong>${money107(l.amount)}</strong></div>`).join('')}<p class="note107">${tr107('Kredit rilisan dicatat terpisah dari saldo royalti.','Release credits are separate from royalty balances.')}</p>`)}
function batchStatus107(b){if(b.archived)return 'archived';const members=[...new Set(b.rows.map(r=>r.member).filter(Boolean))];return b.posted.length===members.length&&b.rows.every(r=>r.matched)?'published':b.block||b.rows.some(r=>!r.matched||!r.member)?'review':'ready'}
function status107(b){const status=batchStatus107(b);return pill107(status==='published'?tr107('Diterbitkan','Published'):status==='ready'?tr107('Siap diterbitkan','Ready to publish'):tr107('Perlu diperiksa','Needs review'),status==='published'?'green':status==='ready'?'':'amber')}
function imports107(){if(!eligible107()||isLabel10())return empty107(tr107('Menu tidak tersedia.','Menu unavailable.'));if(ui107.batch)return batchDetail107();const batches=model107().batches.filter(b=>!b.archived).filter(b=>ui107.importFilter==='all'||batchStatus107(b)===ui107.importFilter);return `<div class="royalty107"><header class="head107"><div><span class="eyebrow107">ROYALTY OPERATIONS</span><h1>${tr107('Laporan & Impor','Reports & Imports')}</h1><p>${tr107('Periksa sumbernya. Terbitkan dengan yakin.','Review the source. Publish with confidence.')}</p></div>${btn107('+ '+tr107('Impor laporan','Import report'),'import','','primary')}</header><nav class="tabs" data-switch-key105="import-filter107">${[['all','Semua','All'],['review','Perlu diperiksa','Needs review'],['ready','Siap diterbitkan','Ready'],['published','Diterbitkan','Published']].map(([id,a,b])=>btn107(tr107(a,b),'import-filter',id,ui107.importFilter===id?'active':'')).join('')}</nav><section class="panel107"><div class="table107"><table><thead><tr>${[tr107('File laporan','Report file'),tr107('Periode','Period'),'Label',tr107('Pemeriksaan','Review'),'Status',''].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${batches.map(b=>`<tr><td><strong>${E(b.name)}</strong><small>${b.id} · ${date107(b.at)}</small></td><td>${[...new Set(b.rows.map(r=>r.period))].map(month107).join(', ')}</td><td>${new Set(b.rows.map(r=>r.member).filter(Boolean)).size}</td><td>${b.rows.filter(r=>r.matched).length} / ${b.rows.length}<small>${tr107('data cocok','matched rows')}</small></td><td>${status107(b)}</td><td>${btn107('↗','batch',b.id,'arrow107')}</td></tr>`).join('')||`<tr><td colspan="6">${empty107(tr107('Belum ada laporan pada kelompok ini.','No reports in this group.'))}</td></tr>`}</tbody></table></div></section></div>`}
function batchDetail107(){const b=Royalty107.batch(model107(),ui107.batch),members=[...new Set(b.rows.map(r=>r.member).filter(Boolean))],tab=ui107.detailTab;return `<div class="royalty107">${btn107('← '+tr107('Laporan & Impor','Reports & Imports'),'back-imports','','text')}<header class="head107"><div><span class="eyebrow107">${b.id} · v${b.version}</span><h1>${E(b.name)}</h1><p>${[...new Set(b.rows.map(r=>r.period))].map(month107).join(' · ')} · ${tr107('Kurs','Exchange rate')} ${money107(b.rate)} / EUR</p></div><div class="actions107">${status107(b)}${ten.role==='super'?btn107(tr107('Tinjau penerbitan','Review publication'),'publish',b.id,'primary'):''}</div></header>${b.block?`<div class="note107">${tr107('Dugaan data ganda. Penerbitan ditahan; bandingkan dengan sumber sebelumnya.','Possible duplicate data. Publication is held; compare with prior sources.')}</div>`:''}<div class="metrics107">${[[tr107('Hak label','Label earnings'),money107(total107(b.rows))],[tr107('Baris laporan','Report rows'),b.rows.length],['Label',members.length],[tr107('Perlu diperiksa','Needs review'),b.rows.filter(r=>!r.matched).length],[tr107('Label diterbitkan','Labels published'),b.posted.length]].map(([a,n])=>`<article class="metric107"><small>${a}</small><strong>${n}</strong></article>`).join('')}</div><nav class="tabs" data-switch-key105="batch-detail107">${[['summary','Ringkasan','Overview'],['review','Perlu diperiksa','Needs review'],['rows','Rincian laporan','Report rows'],['history','Riwayat','History']].map(([id,a,c])=>btn107(tr107(a,c),'batch-tab',id,tab===id?'active':'')).join('')}</nav><section class="panel107">${tab==='summary'?`<h2>${tr107('Pendapatan per label','Earnings by label')}</h2>${members.map(id=>{const rs=b.rows.filter(r=>r.member===id);return `<div class="history107"><div><strong>${E(memberName107(id))}</strong><small style="display:block">${b.posted.includes(id)?tr107('Laporan diterbitkan','Report published'):rs.every(r=>r.matched)?tr107('Siap diterbitkan','Ready to publish'):tr107('Perlu diperiksa','Needs review')}</small></div><strong>${money107(total107(rs))}</strong></div>`}).join('')}${ten.role==='super'?`<div class="actions107" style="margin-top:20px">${btn107(tr107('Catat dana diterima','Record received funds'),'receipt',b.id)}${b.posted.length?btn107(tr107('Ajukan koreksi','Propose correction'),'correction',b.id,'text'):''}</div>`:''}<p class="note107">${tr107('Laporan diterbitkan belum berarti dana tersedia untuk penarikan.','A published report does not mean funds are available for withdrawal.')}</p>${model107().receipts.filter(r=>r.allocations.some(a=>a.batch===b.id)||r.batch===b.id).map(r=>`<div class="history107"><span>${E(r.reference)}<small style="display:block">${r.allocations.length?tr107('Dicocokkan','Matched'):tr107('Menunggu pencocokan','Awaiting matching')}</small></span><strong>${money107(r.amount)}</strong></div>`).join('')}`:tab==='history'?model107().history.filter(h=>h.ref===b.id).slice().reverse().map(h=>`<div class="history107"><div><strong>${eventName107(h.kind)}</strong><p>${E(h.note)}</p><small>${E(h.actor)} · ${date107(h.at)}</small></div></div>`).join('')||empty107(tr107('Belum ada tindakan tercatat.','No recorded actions yet.')):`<div class="table107"><table><thead><tr>${[tr107('Lagu','Track'),'ISRC','Label','Platform',tr107('Pendapatan','Earnings'),''].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${b.rows.filter(r=>tab!=='review'||!r.matched||!r.member).map(r=>`<tr><td>${E(r.title)}<small>${E(r.artist)}</small></td><td>${E(r.isrc||'—')}</td><td>${E(memberName107(r.member))}</td><td>${E(r.platform)}</td><td>${money107(r.amount)}</td><td>${!r.matched||!r.member?btn107(tr107('Cocokkan','Match'),'match',r.id):pill107(tr107('Cocok','Matched'),'green')}</td></tr>`).join('')||`<tr><td colspan="6">${empty107(tr107('Semua data sudah cocok.','All rows are matched.'))}</td></tr>`}</tbody></table></div>`}</section></div>`}
function eventName107(k){return ({import:tr107('Laporan diimpor','Report imported'),match:tr107('Katalog dicocokkan','Catalogue matched'),publish:tr107('Laporan diterbitkan','Report published'),receive:tr107('Dana dicatat','Funds recorded'),correct:tr107('Koreksi diterapkan','Correction applied'),'correction-review':tr107('Koreksi memerlukan penyelesaian','Correction requires resolution'),'unmatched-receipt':tr107('Penerimaan belum dicocokkan','Unmatched receipt')})[k]||k}
